import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Locale;
import java.util.Properties;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file. Any problem with the file or its values is a
 * {@link ConfigException}: the relay never silently falls back to a default for a value that was written.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");
    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        rejectUnknownKeys(properties);
        return new ServiceConfig(
                uri("upstream.url", required(properties, "upstream.url")),
                required(properties, "api.token"),
                intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1),
                intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1),
                intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0),
                duration(properties, "request.timeout"),
                flag(properties, "metrics.enabled"));
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("config file not found: " + file);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read config file " + file + ": " + e.getMessage());
        }
        return properties;
    }

    private static void rejectUnknownKeys(Properties properties) {
        properties.stringPropertyNames().stream()
                .sorted()
                .filter(key -> !KNOWN_KEYS.contains(key))
                .findFirst()
                .ifPresent(key -> {
                    throw new ConfigException("unknown key '" + key + "': check the spelling against the README");
                });
    }

    private static String required(Properties properties, String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            throw new ConfigException(key + " is required");
        }
        return value.trim();
    }

    private static URI uri(String key, String raw) {
        try {
            return new URI(raw);
        } catch (URISyntaxException e) {
            throw new ConfigException(key + " is not a valid URL: '" + raw + "'");
        }
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        int value;
        try {
            value = Integer.parseInt(raw.trim());
        } catch (NumberFormatException e) {
            throw new ConfigException(key + " must be a whole number, got '" + raw + "'");
        }
        if (value < minimum) {
            throw new ConfigException(key + " must be at least " + minimum + ", got " + value);
        }
        return value;
    }

    private static Duration duration(Properties properties, String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            throw new ConfigException(
                    key + " must be a whole number followed by ms, s or m, for example 30s; got '" + raw + "'");
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            throw new ConfigException(key + " is too large: '" + raw + "'");
        }
    }

    private static boolean flag(Properties properties, String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        return switch (raw.trim().toLowerCase(Locale.ROOT)) {
            case "true" -> true;
            case "false" -> false;
            default -> throw new ConfigException(key + " must be true or false, got '" + raw + "'");
        };
    }
}

